mapper.select:
select t.*, d.name deptName
from teacher t
left join dept d on t.dept_id = d.id

  t.name like concat('%',#{name},'%')
  and t.title like concat('%',#{title},'%')
  and t.dept_id = #{deptId} 
  and t.entry_date between #{begin} and #{end}
  and t.salary between #{salaryMin} and #{salaryMax}

order by t.update_time desc

mapper.update:
UPDATE teacher
dept_id = #{deptId}, name = #{name}, title = #{title}, entry_date = #{entryDate}, salary = #{salary}, image = #{image}, update_time = #{updateTime}
WHERE id = #{id}
